def decode(value):
    return (value.replace('@LT@', chr(60)).replace('@GT@', chr(62))
            .replace('@AMP@', chr(38)).replace('@MDASH@', chr(8212)))


def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def function_sources(source):
    tree = ast.parse(source)
    out = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out[node.name] = ast.get_source_segment(source, node)
    return out


def constants(source):
    out = {}
    for node in ast.parse(source).body:
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Constant):
            for target in node.targets:
                if isinstance(target, ast.Name):
                    out[target.id] = node.value.value
    return out


def preservation_checks(before, after, anchors):
    old, new = function_sources(before), function_sources(after)
    for name in PROTECTED:
        # upload_proof is outside the isolated K.1 block but present in full main.py.
        require(name in old and name in new, 'protected function missing: ' + name)
        require(old[name] == new[name], 'protected function changed: ' + name)
    validator = new['_k1_validate'].replace(anchors[7][2], anchors[7][1], 1)
    require(validator == old['_k1_validate'], 'validator changed beyond allowed-key set')
    bc, ac = constants(before), constants(after)
    analyst = ac['K1_ANALYST_TEMPLATE']
    analyst = analyst.replace('Mode: {{mode}}\nMode label: {{mode_label}}\nExtraction targets: {{extract_targets}}\nExpected section types: {{expected_sections}}\n', '', 1)
    analyst = analyst.replace('psychology_notes, ethics_note, mode.\n', 'psychology_notes, ethics_note.\n', 1)
    analyst = analyst.replace('mode: exactly "{{mode}}".\n', '', 1)
    adapter = ac['K1_ADAPTER_TEMPLATE']
    adapter = adapter.replace('Mode: {{mode}}\nMode label: {{mode_label}}\n', '', 1)
    adapter = adapter.replace('next_action, ethics_note, mode.\n', 'next_action, ethics_note.\n', 1)
    adapter = adapter.replace('mode: exactly "{{mode}}".\n', '', 1)
    require(analyst == bc['K1_ANALYST_PROMPT'], 'analyst text changed beyond approved metadata/schema additions')
    require(adapter == bc['K1_ADAPTER_PROMPT'], 'adapter text changed beyond approved metadata/schema additions')
    print('  PASS: protected helpers, upload receipt, validator rules and original prompt/ethics text preserved')


def syntax_check(content):
    with tempfile.TemporaryDirectory(prefix='k15-compile-') as directory:
        path = Path(directory) / 'candidate_main.py'
        path.write_text(content, encoding='utf-8', newline='')
        py_compile.compile(str(path), cfile=str(Path(directory) / 'candidate.pyc'), doraise=True)
    print('  py_compile: PASS (full proposed main.py)')


def isolated_block(content):
    opening = '# ===== BRICK K.1.5: data-driven reverse-engineering modes =====\n'
    closing = '# ===== end BRICK K.1 =====\n'
    require(content.count(opening) == 1 and content.count(closing) == 1, 'K.1 block boundaries not unique')
    start = content.index(opening)
    end = content.index(closing, start) + len(closing)
    return content[start:end]


def atomic_replace(path, payload, mode):
    fd, temp = tempfile.mkstemp(prefix='.brickK15-', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(payload)
            os.fchmod(f.fileno(), mode)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dir', default='.', help='directory containing main.py')
    parser.add_argument('--dry-run', action='store_true')
    args = parser.parse_args()
    path = Path(args.dir).resolve() / 'main.py'
    backup = path.with_name(path.name + '.bak-brickK15')
    raw = path.read_bytes()
    text = raw.decode('utf-8')
    require('BRICK K.1' in text, 'BRICK K.1 is required in main.py')
    require(MARKER not in text, 'BRICK K.1.5 already present; refusing second run')
    require(not backup.exists(), 'main.py.bak-brickK15 exists; it will never be overwritten')
    normalized = text.replace('\r\n', '\n')
    require('\r' not in normalized, 'bare-CR line endings are unsupported')
    crlf = '\r\n' in text
    require(not crlf or '\n' not in text.replace('\r\n', ''), 'mixed LF/CRLF line endings')
    anchors = [(name, decode(old), decode(new), expected) for name, old, new, expected in ANCHORS_ENCODED]
    print('Target: ' + str(path))
    for name, old, new, expected in anchors:
        count = normalized.count(old)
        print('  %s: found %d, expected %d' % (name, count, expected))
        require(count == expected, name + ' exact anchor count mismatch')
    output = normalized
    for name, old, new, expected in anchors:
        output = output.replace(old, new, expected)
    restored = output
    for name, old, new, expected in reversed(anchors):
        restored = restored.replace(new, old, expected)
    require(restored == normalized, 'edit footprint differs from the 20 approved anchors')
    syntax_check(output)
    preservation_checks(normalized, output, anchors)
    block = isolated_block(output)
    ns = {}
    exec(compile(decode(REGRESSION_ENCODED), 'K1 safety regressions', 'exec'), ns)
    ns['offline_tests'](block)
    ns = {}
    exec(compile(decode(MODE_TESTS_ENCODED), 'K15 mode suite', 'exec'), ns)
    ns['k15_tests'](block)
    print('  ALL OFFLINE TESTS PASSED (no external calls)')
    payload = (output.replace('\n', '\r\n') if crlf else output).encode('utf-8')
    if args.dry_run:
        print('DRY RUN PASS: no target or backup written')
        return
    require(path.read_bytes() == raw, 'main.py changed during checks; refusing write')
    mode = stat.S_IMODE(path.stat().st_mode)
    with open(backup, 'xb') as f:
        f.write(raw)
        os.fchmod(f.fileno(), mode)
        f.flush()
        os.fsync(f.fileno())
    atomic_replace(path, payload, mode)
    print('APPLIED: ' + str(path))
    print('BACKUP: ' + str(backup))
    print('Restart e5-ai-coach to load K.1.5.')


if __name__ == '__main__':
    try:
        main()
    except (OSError, UnicodeError, RuntimeError, py_compile.PyCompileError, AssertionError, ValueError) as exc:
        print('ABORT: ' + str(exc), file=sys.stderr)
        print('No successful apply was confirmed. Any created backup remains available.', file=sys.stderr)
        sys.exit(1)
